/**
 * API Tests Aggregator Service
 *
 * Aggregates test status from doc2-api Allure projects for the API (doc2-api) service.
 * Queries environment-specific projects and returns aggregated pass/fail status.
 *
 * Used by /tests page to display current test status for the API service.
 *
 * Test categories:
 * - PyTest Suite (unit/integration tests from doc2-api-pytest-{env})
 * - E2E Tests (end-to-end batch tests from doc2-api-e2e-{env})
 */

import { allureApiService, type AllureTestCase } from '../allure';
import { logger } from 'src/utils/logger';
import type { TestCategoryStatus } from './webTestsAggregator.service';

/**
 * E2E batch definitions (matches GitHub Actions workflow)
 * Each batch represents a logical grouping of E2E tests
 */
export const E2E_BATCHES = [
  { number: 1, name: 'Core Pipeline' },
  { number: 2, name: 'XRechnung + UBL' },
  { number: 3, name: 'EU Core' },
  { number: 4, name: 'EU Nordics + Eastern' },
  { number: 5, name: 'EU Other + Swiss QR' },
  { number: 6, name: 'Latin America' },
  { number: 7, name: 'Asia + Middle East' },
  { number: 8, name: 'Preview Tests' },
  { number: 9, name: 'API + Infrastructure' },
  { number: 10, name: 'New/Experimental' },
] as const;

/**
 * Status for a single E2E batch
 */
export interface E2EBatchStatus {
  batchNumber: number;
  name: string;
  displayName: string;
  allPassing: boolean;
  totalTests: number;
  failedTests: number;
}

/**
 * Overall API service test status
 */
export interface ApiTestsStatus {
  service: 'api';
  displayName: string;
  environment: string; // 'dev', 'stage', 'prod', etc.
  allPassing: boolean;
  categories: TestCategoryStatus[];
  totalTests: number;
  totalFailed: number;
  lastUpdated: Date;
}

/**
 * Service that aggregates test results from all API test categories
 */
export class ApiTestsAggregatorService {
  /**
   * Get test status for API service in current environment
   *
   * Queries all environment-specific Allure projects and returns
   * aggregated pass/fail status for display on /tests page.
   *
   * @param environment - Current environment (dev, stage, prod, etc.)
   * @returns ApiTestsStatus object with all test category statuses
   *
   * @example
   * const status = await apiTestsAggregatorService.getApiTestsStatus('dev');
   * console.log(`All passing: ${status.allPassing}`);
   * console.log(`Total failed: ${status.totalFailed} of ${status.totalTests}`);
   */
  async getApiTestsStatus(environment: string): Promise<ApiTestsStatus> {
    logger.info(`[ApiTestsAggregator] Fetching test status for environment: ${environment}`);

    const categories: TestCategoryStatus[] = [];

    // API uses two separate test projects (pytest and e2e)
    const testCategories = [
      {
        name: 'pytest',
        displayName: 'PyTest Suite',
        projectId: `doc2-api-pytest-${environment}`,
      },
      {
        name: 'e2e',
        displayName: 'E2E Tests',
        projectId: `doc2-api-e2e-${environment}`,
      },
    ];

    // Check status for each category in parallel for better performance
    const categoryPromises = testCategories.map(async (category) => {
      try {
        const report = await allureApiService.getLatestReport(category.projectId);

        const status: TestCategoryStatus = {
          name: category.name,
          displayName: category.displayName,
          projectId: category.projectId,
          allPassing: report
            ? report.statistic.failed + report.statistic.broken === 0
            : false,
          totalTests: report?.statistic.total || 0,
          failedTests: report ? report.statistic.failed + report.statistic.broken : 0,
          lastRunAt: report ? new Date(report.time.stop) : null,
        };

        logger.debug(`[ApiTestsAggregator] ${category.displayName}:`, {
          allPassing: status.allPassing,
          totalTests: status.totalTests,
          failedTests: status.failedTests,
        });

        return status;
      } catch (error) {
        logger.error(`[ApiTestsAggregator] Error fetching ${category.displayName}:`, error);

        // Return failed status on error
        return {
          name: category.name,
          displayName: category.displayName,
          projectId: category.projectId,
          allPassing: false,
          totalTests: 0,
          failedTests: 0,
          lastRunAt: null,
        };
      }
    });

    // Wait for all category statuses
    const resolvedCategories = await Promise.all(categoryPromises);
    categories.push(...resolvedCategories);

    // Calculate overall status
    const allPassing = categories.every((cat) => cat.allPassing);
    const totalTests = categories.reduce((sum, cat) => sum + cat.totalTests, 0);
    const totalFailed = categories.reduce((sum, cat) => sum + cat.failedTests, 0);

    logger.info(`[ApiTestsAggregator] Aggregated status for ${environment}:`, {
      allPassing,
      totalTests,
      totalFailed,
      categoriesChecked: categories.length,
    });

    return {
      service: 'api',
      displayName: 'API Service',
      environment,
      allPassing,
      categories,
      totalTests,
      totalFailed,
      lastUpdated: new Date(),
    };
  }

  /**
   * Get status for a specific test category
   *
   * @param environment - Current environment
   * @param categoryName - Category name (e.g., 'unit', 'integration', 'e2e')
   * @returns TestCategoryStatus or null if not found
   */
  async getCategoryStatus(
    environment: string,
    categoryName: string
  ): Promise<TestCategoryStatus | null> {
    const fullStatus = await this.getApiTestsStatus(environment);
    return fullStatus.categories.find((cat) => cat.name === categoryName) || null;
  }

  /**
   * Group E2E tests by batch label and return batch-level status
   *
   * This method takes an array of test cases (already fetched from Allure)
   * and groups them by their 'batch' label, returning pass/fail status
   * for each batch.
   *
   * @param tests - Array of AllureTestCase objects from E2E project
   * @returns Array of E2EBatchStatus objects for batches with tests
   *
   * @example
   * const tests = await allureApiService.getDetailedTestResults('doc2-api-e2e-dev');
   * const batches = apiTestsAggregatorService.getE2EBatchStatuses(tests);
   * console.log(batches); // [{ batchNumber: 1, name: 'Core Pipeline', ... }]
   */
  getE2EBatchStatuses(tests: AllureTestCase[]): E2EBatchStatus[] {
    // Group tests by batch label
    const batchGroups = new Map<number, AllureTestCase[]>();

    for (const test of tests) {
      const batchLabel = test.labels?.find((l) => l.name === 'batch');
      const batchNum = batchLabel ? parseInt(batchLabel.value, 10) : 0;

      if (!batchGroups.has(batchNum)) {
        batchGroups.set(batchNum, []);
      }
      batchGroups.get(batchNum)!.push(test);
    }

    // Build status for each defined batch
    const batchStatuses = E2E_BATCHES.map((batch) => {
      const batchTests = batchGroups.get(batch.number) || [];
      const failed = batchTests.filter(
        (t) => t.status === 'failed' || t.status === 'broken'
      );

      return {
        batchNumber: batch.number,
        name: batch.name,
        displayName: `Batch ${batch.number}: ${batch.name}`,
        allPassing: failed.length === 0 && batchTests.length > 0,
        totalTests: batchTests.length,
        failedTests: failed.length,
      };
    }).filter((b) => b.totalTests > 0); // Only show batches that have tests

    // Log batch grouping for debugging
    logger.debug('[ApiTestsAggregator] E2E batch statuses:', {
      totalBatches: batchStatuses.length,
      batches: batchStatuses.map((b) => ({
        batch: b.batchNumber,
        tests: b.totalTests,
        failed: b.failedTests,
      })),
    });

    return batchStatuses;
  }
}

// Export singleton instance
export const apiTestsAggregatorService = new ApiTestsAggregatorService();
