/**
 * Blocking Deployment Test Status Prometheus Service (DOCB-13953)
 *
 * All deploy-blocking test data for all services comes from a SINGLE Prometheus
 * query. A Prometheus selector matches several metric families at once, so one
 * HTTP request returns every metric for every service as one flat vector — no
 * per-service and no per-metric fan-out. The flat array is grouped client-side
 * by service + environment + track, then dispatched on __name__.
 *
 * Architecture decision (mirrors sentinelLogApi.service.ts):
 *   Base URL: https://prometheus.docbits.com — fixed, NOT env-prefixed.
 *   A single Prometheus instance serves every environment; the environment is
 *   a metric LABEL, so it is filtered inside the query rather than in the host.
 *
 * Metric schema — `docbits_deploy_blocking_*`, every family a gauge carrying
 * service + environment + track, and all but _run_info also repo:
 *   *_status{service,environment,track,repo}              1 = allowed to deploy, 0 = blocked
 *   *_configured{service,environment,track,repo}          1 = gate wired up, 0 = nothing gates it
 *   *_timestamp_seconds{service,environment,track,repo}   unix seconds, when the producer pushed
 *   *_tests_total{service,environment,track,repo,result}  result = passed|failed
 *   *_run_info{service,environment,track,run_id,commit,image_tag,blocked_by}
 *                                                        always 1; the labels carry the payload
 *
 * `track` is `vesta` or `nova` — the release line, derived centrally by the
 * collector from the ref. DocBits ships two lines through ONE set of
 * environments, so `environment` alone does not identify a deployment: the
 * `-nova` segment is stripped out of it and reported as `track` instead, which
 * is why `dev-nova` arrives as environment="dev", track="nova" rather than as a
 * sixth environment. See TRACK_LABEL and AGGREGATION_LABELS for what that means
 * for reading it, and DEFAULT_TRACK for the samples pushed before it existed.
 *
 * WHY A WINDOW QUERY AND NOT AN INSTANT QUERY
 * -------------------------------------------
 * The producer pushes these metrics to a Pushgateway, which holds each group in
 * memory and re-serves it on every scrape. A group the gateway stops holding —
 * pod rescheduled, group deleted — stops producing samples instantly, and an
 * instant query then returns nothing for a service whose history Prometheus
 * still has in full. On 2026-08-12 a gateway reschedule dropped every group at
 * once: samples stopped dead and this table went blank while the data was
 * intact. So the freshness of these series measures the GATEWAY, never the
 * service.
 *
 * Every read therefore asks for a window — last_over_time(…[7d:5m]) — and the
 * age of a verdict comes from *_timestamp_seconds instead. A verdict without
 * its age is not a status: with a window query the series no longer disappears,
 * which makes age the only thing separating "green two minutes ago" from "green
 * four days ago". Age is therefore always carried and always rendered — but as
 * a plain fact beside the verdict, never as a verdict of its own. See
 * gateState() for why no age threshold exists.
 *
 * The read contract is DevOps/.github/docs/DEPLOY_GATE_METRICS.md; keep this
 * file in step with it.
 */

import axios from 'axios';
import { logger } from 'src/utils/logger';

// ============================================================================
// Constants
// ============================================================================

const PROMETHEUS_URL = 'https://prometheus.docbits.com';

/**
 * How far back a read looks, and at what resolution.
 *
 * 7d covers the realistic gap between two pipeline runs of a quiet repo and
 * stays well inside the 30d Prometheus retention. Declared once and used by
 * every query built here, so widening the window is a one-line change.
 */
export const METRIC_WINDOW = '7d';
const METRIC_WINDOW_STEP = '5m';

/**
 * The metric families this file dispatches on, named explicitly rather than
 * matched with `_.+`.
 *
 * Two reasons. The suite_* family is about four fifths of the series and is not
 * consumed, and over a window that payload only grows. And naming the families
 * is what lets AGGREGATION_LABELS below name every label that has to survive.
 *
 * `configured` is load-bearing, not decoration: a service with no
 * deployment-blocking tests deliberately publishes NO _status series at all,
 * rather than faking a green verdict, so the fleet must be enumerated from
 * _configured. ideas-service is in exactly that state and vanishes from the
 * table if this family is dropped.
 */
/**
 * `suites_total` is consumed for ONE reason: it is the only family that
 * separates "the gate never ran" from "the gate ran partially and was cut
 * short". Both publish no verdict, both carry `blocked_by="did-not-run"`, and
 * both would otherwise be described as unmeasured — but doc2app's interrupted
 * runs carry 13-14 real passed tests across 1 real suite, and calling that "no
 * measurement" throws away true data. Adding the family widens what the query
 * RETURNS; it changes no metric name, no label, no window and no grouping key.
 */
const CONSUMED_METRICS = [
  'status',
  'configured',
  'timestamp_seconds',
  'run_info',
  'tests_total',
  'suites_total',
];

/**
 * The rollout outcome, which is a DIFFERENT family and not a blocking suffix.
 *
 * `docbits_deploy_blocking_*` is decided BEFORE Helm runs: status=1 means "this
 * service was allowed to deploy", never "it deployed". Until DEVO-150 the actual
 * Helm result was computed in Actions and thrown away, so a green gate followed
 * by a failed rollout read green here. This family closes that gap and is the
 * ONLY source of true rollout success.
 *
 * It shares the gate family's grouping key (service/environment/track), so it
 * folds onto the same row with no join of our own — hence the one selector below
 * reads both families in a single request.
 */
const DEPLOY_OUTCOME_METRIC = 'docbits_deploy_outcome';

/**
 * The rollout results the producer stamps on `deploy_result`.
 *
 * `skipped` is a first-class value, not an absence: a deploy the gate stopped,
 * or one a pipeline never reached, is "not deployed" — which is emphatically not
 * a success. See DEVO-147 for what publishing a fabricated success costs.
 */
export const DEPLOY_RESULTS = ['success', 'failure', 'skipped'] as const;
export type DeployResult = (typeof DEPLOY_RESULTS)[number];

/**
 * Which stage of the deployment broke — the producer's own closed vocabulary.
 *
 * The reason this is worth having ALONGSIDE `blocked_by`: blocked_by is whatever
 * the caller named its jobs, free text across two producer generations, so
 * reading it needs the hand-maintained BLOCKED_BY_CLASS allow-list below and
 * that list goes stale silently whenever a workflow is renamed. These values are
 * defined by us (DEVO-150) and can simply be switched on.
 *
 * `rollout` is the ONLY value that indicts the deployment itself. Everything
 * else means the deploy never ran — which is the distinction Gregor asked for:
 * was it the deployment, or was it something before it?
 *
 * Ordered root-cause-first by the producer, so the value already names the cause
 * rather than a symptom: a migration failure reports `migration`, not the
 * `rollout` that was skipped because of it.
 */
export const DEPLOY_STAGES = [
  'none',
  'upstream',
  'version',
  'chain-validation',
  'migration',
  'tests',
  'rollout',
  'unknown',
] as const;
export type DeployStage = (typeof DEPLOY_STAGES)[number];

/** How each stage is named to a human, in the deployment column. */
export const DEPLOY_STAGE_REASON: Record<Exclude<DeployStage, 'none'>, string> = {
  upstream: 'failed before the deploy (build or checkout)',
  version: 'failed at version tagging',
  'chain-validation': 'failed at the release-chain check',
  migration: 'failed at a database migration',
  tests: 'blocked by the test gate',
  // The one that is actually about the deployment.
  rollout: 'the Helm rollout itself failed',
  unknown: 'not deployed, and CI named no stage',
};

/**
 * THESE TRACKS ARE BRANCH LINES — NOT THE APP'S RELEASE CHANNELS
 * -------------------------------------------------------------
 * `vesta` and `nova` are the values the CI collector stamps on every series,
 * derived from the ref it ran on: branch `dev` — and `stage`, `sandbox`, `demo`,
 * `prod` — pushes track="vesta"; branch `dev-nova` pushes track="nova". They
 * name a BRANCH LINE and nothing else.
 *
 * `src/utils/release-names.ts` uses the same two proper nouns for the product's
 * release CHANNELS. Before DEVO-135 the two mappings ran in OPPOSITE
 * directions (branch `dev` was "Nova" to the product's old `latest` channel
 * but "vesta" to this collector) — that inversion is what this whole comment
 * block used to warn against reconciling. DEVO-135 renamed the channel enum
 * itself to `vesta`/`nova`, so the two now agree on the STRING VALUE.
 *
 * They still are not the same AXIS, though: a track is a branch line — every
 * org deployed on `dev` (whatever their individual release_channel) reports
 * track="vesta" here, because the CI collector stamps it from the ref it ran
 * on, not from any org's channel. Rendering a bare "VESTA"/"NOVA" would still
 * read as "this org's channel", which it isn't — hence trackLabel() naming the
 * branch line instead of the bare track value. See "THE TRACK TOGGLE IS
 * TRANSITIONAL" below for why the two axes aren't unified yet.
 *
 * THE TRACK TOGGLE IS TRANSITIONAL
 * --------------------------------
 * A user-selectable track is not the intended end state. The frontend will
 * eventually route the two lines separately — mirroring the deployment twice —
 * and each board will show only its own line, derived automatically, exactly as
 * `environment` is already derived from APP_VUE_STAGE and deliberately not
 * user-selectable. The input for that already exists: a company's channel comes
 * from /v2/users/me/organisations (`release_channel`, see
 * src/sdk/auth/models/meOrganisationItem.ts), is read by getCurrentChannel() in
 * src/pages/api-base-url.ts, and is surfaced in Settings → Company → Release
 * Channel (src/pages/Settings/Components/Company/ReleaseChannel.vue).
 *
 * That derivation is nevertheless BLOCKED today, and not by the naming (DEVO-135
 * fixed the naming): the product and the metrics still split on different axes.
 * The product splits by per-org channel within ONE environment — `nova` builds
 * the /nova/ bundle from a per-env `nova`/`nova-stage`/... branch, `vesta`
 * builds the root bundle from that same environment's normal branch (`dev`,
 * `stage`, ...). The metrics split by branch line across environments — `dev`
 * is vesta, `dev-nova` is nova. Every org on `dev` is thus built from a
 * non-`-nova` branch and resolves to track="vesta" regardless of its own
 * release_channel: deriving the track from a company's release channel today
 * would render two IDENTICAL boards. And `dev-nova`, the only source of
 * track="nova", feeds no per-org channel deployment at all — it's a separate,
 * full environment, not the source of the /nova/ bundle above.
 *
 * The prerequisite is that the deployed lines and the branch lines become the
 * same axis: that the /nova/ bundle and the root bundle are built from the two
 * branches the collector labels (i.e. `dev`/`dev-nova` directly, not a third
 * per-env `nova` branch). Until then the toggle stays, because it is the only
 * way to see that the nova line exists at all.
 */
const TRACK_LABEL = 'track';

/**
 * The two branch lines, in the order they are offered.
 *
 * VESTA is the line that ships today (`dev`, `stage`, `sandbox`, `demo`,
 * `prod`); NOVA is the `-nova` twin of each. Both build the same services into
 * the same environments, so a verdict is only identified by all three of
 * service + environment + track.
 */
export const RELEASE_TRACKS = ['vesta', 'nova'] as const;
export type ReleaseTrack = (typeof RELEASE_TRACKS)[number];

/**
 * What each line appends to an environment's branch name. VESTA deploys the
 * plain environment branch, NOVA its `-nova` twin.
 */
const TRACK_BRANCH_SUFFIX: Record<ReleaseTrack, string> = { vesta: '', nova: '-nova' };

/**
 * The branch line a track means, in one environment: `dev` / `dev-nova` on the
 * dev deployment, `stage` / `stage-nova` on stage.
 *
 * Falls back to the dev line when no environment is given, so a caller without
 * one still gets an unambiguous name rather than a bare track value.
 */
export function trackBranchLine(track: ReleaseTrack, environment?: string): string {
  return `${environment || 'dev'}${TRACK_BRANCH_SUFFIX[track]}`;
}

/**
 * How a track is named in the UI — `VESTA (dev)`, `NOVA (dev-nova)`.
 *
 * The parenthesised branch is not decoration: it is the only part of the label
 * that is unambiguous. "VESTA" alone means the other line in this same app —
 * Settings → Company → Release Channel calls the `frozen` channel Vesta and the
 * `latest` channel Nova, the inverse of these values. Naming the branch line
 * says which of the two a reader is looking at without having to know that.
 */
export function trackLabel(track: ReleaseTrack, environment?: string): string {
  return `${track.toUpperCase()} (${trackBranchLine(track, environment)})`;
}

/**
 * What a series with no `track` label is taken to mean.
 *
 * `track` joined the metric schema — and the Pushgateway grouping key — after
 * every service had already been reporting for weeks, and Prometheus keeps 30
 * days while this file reads 7. Those older samples are not noise: they are the
 * only thing many services have until their next pipeline run, because a recent
 * gateway restart cleared most groups.
 *
 * They are read as VESTA rather than filtered out, which is both the safe and
 * the factually correct choice. Correct, because every push that predates the
 * label came off `dev`/`stage`/`prod` — NOVA had no reporting pipeline at all.
 * Safe, because the alternative — a `track!=""` matcher — would make every
 * service that has not re-run since the change DISAPPEAR from the board, and a
 * service silently missing is worse than a service shown under the line it
 * actually deployed on.
 */
export const DEFAULT_TRACK: ReleaseTrack = 'vesta';

/**
 * Matchers that keep the result to real services in real environments.
 *
 * The `environment` matcher drops pushes from PR check runs — `270/merge`,
 * `feat/DOCB-42` — by excluding any environment name containing a slash. No
 * real environment name does and every branch ref does, so the filter needs no
 * maintenance as new ones appear. PR runs no longer push at all, but the ones
 * that already did stay for the retention window, and one of them is held
 * permanently fresh by the gateway.
 *
 * `service!~"poc-.*"` drops the proof-of-concept groups from the original
 * spike. A window query needs this where an instant query did not: those
 * gateway groups were deleted, so they are invisible to an instant query, but
 * five of them are still inside 7d.
 */
const REAL_SERIES_MATCHERS = ['environment!~".*/.*"', 'service!~"poc-.*"'];

/**
 * The labels the aggregation keeps. Everything not listed — `pod`, `instance`,
 * `container`, `endpoint`, `namespace`, `job` — is scrape-target metadata.
 *
 * `pod` is the one that matters. honorLabels preserves the pusher's labels, but
 * the scrape still attaches the gateway pod, so every gateway reschedule starts
 * a SECOND series per group, identical except for `pod`; over a window both are
 * returned. The aggregation must sit INSIDE the subquery, as it does below,
 * because each evaluation step then sees only the pod that was live at that
 * step. Aggregating outside the window instead mixes a dead pod's last value
 * with a live one's, and `max` would report green where the newest push was red.
 *
 * `__name__` is in the list on purpose. An aggregation drops the metric name
 * unless `by` names it, and `by` is the only form that can keep it — `without`
 * drops it unconditionally. Without the name nothing downstream can tell a
 * status from a timestamp.
 *
 * `track` is in the list for a harder reason, and it is the one entry here that
 * must never be "simplified" away. An aggregation keeps only what it groups by,
 * so dropping `track` does not merely lose a label: it merges the VESTA and NOVA
 * verdicts of one service into a SINGLE series, and `max` then returns the
 * greener of the two. A red NOVA gate would hide behind a green VESTA one and
 * the board would report that a blocked deployment was allowed — the exact
 * false-green this metric family exists to make impossible. Two release lines
 * deploy the same services into the same environments, so service +
 * environment does not identify a deployment; only service + environment +
 * track does.
 */
const AGGREGATION_LABELS = [
  '__name__',
  'service',
  'environment',
  TRACK_LABEL,
  'repo',
  'result',
  'run_id',
  // A re-run KEEPS its run id and only advances this, so without it the
  // aggregation folds a run's attempts into one series and `max` returns the
  // greener of them — a re-run that turned a pass into a real failure would be
  // reported as the pass. See isNewerPush().
  'run_attempt',
  'commit',
  'image_tag',
  // Carries success|failure|skipped for DEPLOY_OUTCOME_METRIC. Named here for
  // the same reason `track` is: an aggregation keeps only what it groups by, so
  // dropping it would collapse a failed rollout and a skipped one into one
  // series and `max` would report the kinder of the two.
  'deploy_result',
  // Which STAGE broke. Same reason again — and this one is the difference
  // between "the deployment failed" and an answer somebody can act on.
  'failed_stage',
];

/**
 * Only the current metric family is read.
 *
 * The gate originally published under `docbits_critical_tests_*`; CI renamed it
 * to `docbits_deploy_blocking_*` and the old family stopped reporting on
 * 2026-08-10. Matching both was free for an instant query, because a retired
 * family simply returns nothing. Over a window it is not free: the retired
 * family comes back for as long as it is in retention, carrying the `service`
 * spellings it used at the time — `importemail-service`, `ocr`, `fulltext`,
 * `import-ftp-service`. Those resolve to the same display names as the current
 * labels, so the table would grow a second, permanently stale row for services
 * that are reporting normally. Reading one family is what keeps one service to
 * one row. metricSuffix() still normalizes the old names, so a payload
 * containing them is parsed correctly if one ever appears.
 *
 * @param environment - when given, filtered server-side via a label matcher
 * @param track - when given, restricts the read to one release line
 */
function seriesSelector(environment?: string, track?: ReleaseTrack): string {
  const matchers = [
    `__name__=~"docbits_deploy_(blocking_(${CONSUMED_METRICS.join('|')})|outcome)"`,
    ...REAL_SERIES_MATCHERS,
    ...(environment ? [`environment="${environment}"`] : []),
    ...(track ? [trackMatcher(track)] : []),
  ];
  return `{${matchers.join(',')}}`;
}

/**
 * Match one release line, including the samples pushed before `track` existed.
 *
 * An absent label is the empty string to a matcher, so `track="vesta"` would
 * exclude every pre-track series — see DEFAULT_TRACK for why that is the one
 * outcome to avoid. `track=~"vesta|"` is anchored by Prometheus as
 * `^(?:vesta|)$` and therefore matches both the label and its absence, which
 * makes reading VESTA server-side safe. NOVA needs no such alternative: no
 * pre-track sample can belong to a line that was not reporting yet.
 *
 * The page does not use this — it reads both lines in one request so it can
 * report which lines report at all — but a Grafana panel or a manual curl for a
 * single line should build the matcher here rather than by hand.
 */
function trackMatcher(track: ReleaseTrack): string {
  return track === DEFAULT_TRACK
    ? `${TRACK_LABEL}=~"${track}|"`
    : `${TRACK_LABEL}="${track}"`;
}

/** The bare selector with no environment filter. Handy for a manual curl. */
export const BLOCKING_TESTS_SELECTOR = seriesSelector();

/**
 * The one query every read of these metrics issues.
 *
 * Every call site — with and without an environment, with and without a track —
 * goes through here, so the window, the filters and the aggregation cannot drift
 * apart between them.
 */
export function buildBlockingStatusQuery(environment?: string, track?: ReleaseTrack): string {
  const selector = seriesSelector(environment, track);
  const aggregated = `max by (${AGGREGATION_LABELS.join(', ')}) (${selector})`;
  return `last_over_time(${aggregated}[${METRIC_WINDOW}:${METRIC_WINDOW_STEP}])`;
}

/**
 * Prometheus adds labels of its own (job, instance, and under Thanos possibly
 * receive/replica/tenant_id). Series are keyed on service + environment + track
 * only — never on these.
 *
 * `track` has to be part of the key for the same reason it has to survive the
 * aggregation: the fold below is a Map, so a key that cannot tell VESTA from
 * NOVA is last-writer-wins between two different deployments' results, and
 * Prometheus does not order its result. One of the two verdicts would simply
 * vanish, chosen at random.
 */
const GROUPING_LABELS = ['service', 'environment', TRACK_LABEL] as const;

// Plain axios instance: Prometheus is unauthenticated and the app's interceptors
// would attach auth headers that turn the preflight into a CORS failure.
const prometheusAxios = axios.create({
  baseURL: PROMETHEUS_URL,
  timeout: 20000,
  headers: { Accept: 'application/json' },
});

// ============================================================================
// Response types
// ============================================================================

export interface PromVectorResponse {
  status: 'success' | 'error';
  data: {
    resultType: 'vector';
    result: Array<{ metric: Record<string, string>; value: [number, string] }>;
  };
}

/** One service's deploy-blocking test gate verdict in one environment, on one track. */
export interface ServiceBlockingStatus {
  service: string;
  environment: string;
  /**
   * Release line this verdict belongs to — `vesta` or `nova`. Never empty: a
   * series pushed before the label existed reads as DEFAULT_TRACK.
   */
  track: string;
  passed: boolean;
  /**
   * When the producer pushed this verdict, or the epoch when no
   * *_timestamp_seconds series exists.
   *
   * The verdict's age, and the only source of it. Rendered next to the verdict
   * on every row and never folded into it: several services deploy about once a
   * week by design, so age says how current a verdict is and nothing about
   * whether it is good. See gateState().
   */
  finishedAt: Date;
  counts: { passed: number; failed: number; skipped: number };
  runId?: string;
  /**
   * Which attempt of `runId` published this. A re-run keeps the run id, so this
   * is the only thing that separates a run's original push from its re-run —
   * see isNewerPush().
   */
  runAttempt?: string;
  commit?: string;
  imageTag?: string;
  /**
   * What stopped the deploy, verbatim from the `blocked_by` label on
   * *_run_info: `tests` when the gate ran and failed, `did-not-run` when the
   * pipeline skipped its gate jobs and never reached a verdict at all.
   *
   * Always the marker of the NEWEST run in the window, never whichever series
   * the result happened to list last: a window returns one run_info per run, so
   * it is assigned under the same run-id ordering as `runId`/`commit` (see
   * isNewerRun). A newer clean run therefore CLEARS an older `did-not-run`,
   * which is what makes the row recover by itself on the next real deploy.
   *
   * Undefined for the many pushes that carry no such label. Load-bearing rather
   * than decorative: it is the only evidence that a verdict inside the window
   * belongs to an earlier run than the one being described — see
   * verdictSuperseded().
   */
  blockedBy?: string;
  // --- extras beyond the ticket's model, needed to render honestly ---
  /** Source repository, e.g. DocBits_DocNet */
  repo?: string;
  /** Gate wired up in CI. False when *_configured reports 0. */
  configured: boolean;
  /** True when a *_status series exists at all. */
  hasStatus: boolean;
  /** Total tests counted across every result bucket. */
  totalTests: number;
  /**
   * How many blocking test suites the run reported, or undefined when the
   * service published no *_suites_total series at all.
   *
   * Read only to answer "did anything actually execute?" — see gateState().
   * Never rendered as a count of its own and never used to judge a verdict: a
   * one-suite gate is not worse than a ten-suite gate.
   */
  suites?: number;
  /**
   * False for placeholder rows added from the known-service registry — the
   * service exists in the app but Prometheus has no gate series for it at all.
   */
  hasMetrics: boolean;
  // --- rollout outcome (DEVO-150), independent of the gate above ------------
  /**
   * Whether a `docbits_deploy_outcome` series exists for this row at all.
   *
   * Separate from `deployOk` because the absent case is not a third truth value
   * to be squeezed into a boolean: no series means the producer has not run for
   * this service yet, which is "unknown" and must fall back to `blockedBy`
   * rather than read as a failure. See deploymentState().
   */
  hasDeployOutcome: boolean;
  /** True when the Helm upgrade and rollout actually succeeded. */
  deployOk?: boolean;
  /** Verbatim `deploy_result` label: success | failure | skipped. */
  deployResult?: string;
  /**
   * The run the rollout outcome came from, used ONLY to order two outcome samples
   * against each other.
   *
   * Separate from `runId`, which orders the gate's own `_run_info`: the two
   * families are pushed by the same run today, but nothing guarantees a window
   * holds the same newest run for both, and sharing one field would let a newer
   * gate verdict silently promote an older rollout result.
   */
  deployRunId?: string;
  /**
   * The ATTEMPT of `deployRunId` this outcome came from, and the reason the pair
   * has to be carried rather than the run id alone: a re-run keeps its run id.
   *
   * Undefined for series pushed before DEVO-175 added the label, which
   * isNewerPush() treats as attempt 1 — so a genuine attempt 2 outranks them and
   * two unlabelled samples keep the held one, stably.
   */
  deployRunAttempt?: string;
  /**
   * Verbatim `failed_stage` label — which stage broke, from the producer's closed
   * set (see DEPLOY_STAGES). `none` on a successful rollout, `unknown` where the
   * deploy did not succeed and nothing named a stage.
   *
   * Preferred over `blockedBy` for the reason shown to a human, because it cannot
   * go stale as callers rename their jobs. Undefined for series pushed before
   * DEVO-150 added the label.
   */
  failedStage?: string;
}

/**
 * Rendered state of a card. Deliberately more granular than pass/fail: a gate
 * that reports success while having run zero blocking tests is not a genuine
 * pass, and a service that publishes nothing is neither a pass nor a failure.
 *
 * Age is NOT one of these. It is reported alongside, not as a state — see
 * gateState().
 */
export type BlockingGateState =
  | 'failing'
  | 'passing'
  | 'no-tests'
  | 'did-not-run'
  | 'incomplete'
  | 'not-configured'
  | 'no-metrics';

// ============================================================================
// Pure helpers (unit tested)
// ============================================================================

/**
 * Strip either metric-family prefix so both families dispatch identically.
 * `docbits_deploy_blocking_tests_total` and `docbits_critical_tests_total`
 * both reduce to `total`.
 */
export function metricSuffix(metricName: string): string {
  return metricName
    .replace(/^docbits_critical_tests_/, '')
    .replace(/^docbits_deploy_blocking_/, '')
    // Not a blocking suffix: the rollout family sits beside that prefix rather
    // than under it, so it is normalized to its own suffix explicitly.
    .replace(new RegExp(`^${DEPLOY_OUTCOME_METRIC}$`), 'outcome')
    .replace(/^tests_total$/, 'total');
}

/**
 * The release line a series belongs to, with a missing label resolved.
 *
 * Every caller must go through here rather than reading `metric.track`, so that
 * a pre-track series and the same service's track-bearing series agree on their
 * line and therefore fold onto ONE row instead of two — see DEFAULT_TRACK.
 */
export function metricTrack(metric: Record<string, string>): string {
  return metric[TRACK_LABEL] || DEFAULT_TRACK;
}

/**
 * Group key — service + environment + track, ignoring infrastructure labels.
 *
 * `track` resolves through metricTrack() rather than being read raw, so a
 * service reporting both before and after the label landed keys onto one row
 * instead of growing a duplicate that differs only by having no track.
 */
export function seriesKey(metric: Record<string, string>): string {
  // Joined on an escaped NUL rather than a raw one: a literal control byte in
  // the source makes the file read as binary to grep/rg and other tooling.
  return GROUPING_LABELS.map((label) =>
    label === TRACK_LABEL ? metricTrack(metric) : (metric[label] ?? '')
  ).join('\u0000');
}

/**
 * True when `candidate` is a later run than `current`.
 *
 * GitHub run ids increase monotonically, so the largest is the most recent run.
 * A non-numeric id never wins against a numeric one, and never loses to one.
 */
function isNewerRun(candidate: string | undefined, current: string): boolean {
  if (candidate === undefined) return false;
  const next = Number(candidate);
  if (Number.isNaN(next)) return false;
  const previous = Number(current);
  if (Number.isNaN(previous)) return true;
  return next > previous;
}

/** How a sample identifies the push that produced it. */
interface PushOrder {
  runId?: string;
  runAttempt?: string;
}

/**
 * True when `candidate` is a later PUSH than `current` — a later run, or the
 * same run re-run.
 *
 * Run id first, because it orders runs. Attempt only breaks a tie within one
 * run, and it has to: a re-run keeps its id, so on run id alone the two
 * attempts are indistinguishable and the fold would keep whichever arrived
 * first. Attempt 2 of a run is that run's current word on itself.
 *
 * A sample carrying no run id at all loses to one that does. Those predate the
 * labels and are therefore older by construction — the same argument
 * schemaGeneration() makes for `track`.
 */
function isNewerPush(candidate: PushOrder, current: PushOrder): boolean {
  if (candidate.runId === undefined) return false;
  if (current.runId === undefined) return true;
  if (isNewerRun(candidate.runId, current.runId)) return true;
  if (isNewerRun(current.runId, candidate.runId)) return false;
  // Same run: the later attempt speaks for it.
  return Number(candidate.runAttempt ?? 1) > Number(current.runAttempt ?? 1);
}

/**
 * The families one run publishes together, in ONE `PUT` of the gate group.
 *
 * They therefore share a run id and are ordered as a unit — see the pre-pass in
 * groupBlockingStatuses(). `outcome` is deliberately absent: it lives in its own
 * gateway group (`job="deploy-outcome"`) and a run that publishes an outcome may
 * legitimately publish no verdict, so ordering it against the verdict would let
 * a newer rollout discard an older, still-current gate result.
 *
 * `timestamp_seconds` is absent for a different reason: it carries no run id and
 * is ordered by its own value, which is the one honest clock in the family.
 */
const VERDICT_SUFFIXES = new Set(['status', 'configured', 'total', 'suites_total', 'run_info']);

function emptyStatus(metric: Record<string, string>): ServiceBlockingStatus {
  return {
    service: metric.service ?? 'unknown',
    environment: metric.environment ?? 'unknown',
    // A series pushed before `track` existed is VESTA, not 'unknown' and not a
    // row to be dropped — see DEFAULT_TRACK.
    track: metricTrack(metric),
    passed: false,
    finishedAt: new Date(0),
    counts: { passed: 0, failed: 0, skipped: 0 },
    configured: true,
    hasStatus: false,
    totalTests: 0,
    hasMetrics: true,
    hasDeployOutcome: false,
  };
}

/**
 * Services whose series are still inside the retention window but which will
 * never report a verdict again, so their row is noise rather than information.
 *
 * `fulltext-ai` became a single shared GPU deployment in May 2026 and its entry
 * was removed from DevOps/services/registry.yaml at the same time. Its `dev`
 * pipeline now fails at the first job with "Repo 'DocBits_Fulltext_AI' not found
 * in registry" and it has not deployed from `dev` since 2026-05-05, so the grey
 * "no gates" row it produces describes a pipeline that cannot run rather than a
 * service awaiting tests.
 *
 * This is NOT the place for a service that merely has no gate yet —
 * `ideas-service` reports configured=0 today and keeps its row, because that is
 * a true statement about a live pipeline and it has a real gate landing.
 */
const RETIRED_SERVICES = new Set(['fulltext-ai']);

/**
 * Which schema revision pushed a series: 1 once the collector labelled the
 * release line, 0 for everything pushed before it.
 *
 * This orders the two, which is what makes reading a missing `track` as VESTA
 * safe. `track` joined the Pushgateway GROUPING KEY, so every group pushed
 * before the change is keyed on a tuple no producer will ever write again:
 * nothing overwrites it, the gateway has no TTL, and it is re-served on every
 * scrape — so it keeps reporting the verdict it held on the day of the change,
 * indefinitely. Both it and the service's real series now fold onto the same
 * VESTA row, and the pre-track one is older BY CONSTRUCTION: the schema changed
 * at a point in time and no push after it omits the label.
 */
function schemaGeneration(metric: Record<string, string>): number {
  return metric[TRACK_LABEL] ? 1 : 0;
}

/**
 * Fold the flat Prometheus vector into one entry per service + environment +
 * track.
 *
 * Takes no clock: nothing here compares a timestamp against "now". The verdict's
 * age is derived where it is displayed, so it stays live between the five-minute
 * refreshes rather than being frozen at fold time.
 *
 * @param result - the `data.result` array as returned by buildBlockingStatusQuery
 */
export function groupBlockingStatuses(
  result: PromVectorResponse['data']['result']
): ServiceBlockingStatus[] {
  const byKey = new Map<string, ServiceBlockingStatus>();

  // Drop retired services before they ever become a row. Filtering here rather
  // than in the query keeps the PromQL readable and the reason documented, and
  // it applies to every consumer of this grouping.
  const samples = result.filter(
    ({ metric }) => !RETIRED_SERVICES.has((metric.service ?? '').toLowerCase())
  );

  // Where a row has both a pre-track and a track-bearing series, the
  // track-bearing one is the whole truth and the other must not contribute a
  // single field. Not just the ones with an ordering guard below — `status`,
  // `configured` and the counts have no timestamp to order them by, so without
  // this they would be last-writer-wins over an unordered Prometheus result,
  // and a stale green could overwrite a fresh red. Resolving the generation per
  // key up front makes that independent of the order the series arrive in.
  const newestGeneration = new Map<string, number>();
  for (const { metric } of samples) {
    const key = seriesKey(metric);
    const generation = schemaGeneration(metric);
    if (generation > (newestGeneration.get(key) ?? -1)) {
      newestGeneration.set(key, generation);
    }
  }

  // WHICH RUN DOES THIS ROW'S VERDICT BELONG TO? (DEVO-161)
  //
  // The verdict families now carry `run_id`, so a run is a distinct SERIES
  // rather than a new value on one — and a windowed read hands back every run
  // inside the window. Without a rule the fold is last-writer-wins over an
  // order Prometheus does not define, which is how the same read of `_run_info`
  // and `docbits_deploy_outcome` went wrong before it was ordered by run id.
  //
  // So: resolve the newest push per key up front, then let only that push
  // contribute. Up front rather than inline, because the families arrive
  // interleaved and `status` cannot be ordered against a `configured` it has
  // not seen yet.
  //
  // This is the CONSUMER half of the fix. The producer already refuses to push
  // once it knows it has been superseded, but that guard is deliberately
  // fail-open — an unreachable gateway lets a stale run through. When that
  // happens the newer run's series is still inside the window, and this makes
  // the board show it instead of needing the group repaired by hand.
  //
  // Scoped to the families one PUT publishes together. `outcome` orders itself
  // separately because it is a separate gateway group: a run can publish a
  // rollout outcome and no verdict, and ordering the two together would let it
  // erase a gate result that is still current.
  const newestPush = new Map<string, PushOrder>();
  // Which families have actually started carrying a run id, per key. A verdict
  // family only gained one on 2026-09-01, and `_run_info` has had one far
  // longer — so "this sample has no run id" means "it predates the labels" only
  // where a sample OF ITS OWN FAMILY has one. Judging it against another
  // family's run id would drop every `_status` in the fleet for as long as any
  // producer is still on the old payload, which is the whole of the rollout.
  const identified = new Map<string, Set<string>>();
  for (const { metric } of samples) {
    const suffix = metricSuffix(metric.__name__ ?? '');
    if (!VERDICT_SUFFIXES.has(suffix)) continue;
    if (metric.run_id === undefined) continue;
    const key = seriesKey(metric);
    // GENERATION OUTRANKS RUN ID, the same precedence the fold below applies.
    // A pre-track series is older by construction however high its run id is —
    // and its id can be higher, because the orphaned group is re-served forever
    // while nothing overwrites it. Letting it set the bar here would disqualify
    // the series that actually describes the service and leave the row with no
    // sample at all.
    if (schemaGeneration(metric) < (newestGeneration.get(key) ?? 0)) continue;

    const families = identified.get(key) ?? new Set<string>();
    families.add(suffix);
    identified.set(key, families);

    const candidate: PushOrder = { runId: metric.run_id, runAttempt: metric.run_attempt };
    const held = newestPush.get(key);
    if (held === undefined || isNewerPush(candidate, held)) {
      newestPush.set(key, candidate);
    }
  }

  const entryFor = (metric: Record<string, string>): ServiceBlockingStatus => {
    const key = seriesKey(metric);
    let entry = byKey.get(key);
    if (!entry) {
      entry = emptyStatus(metric);
      byKey.set(key, entry);
    }
    if (metric.repo) {
      entry.repo = metric.repo;
    }
    return entry;
  };

  for (const { metric, value } of samples) {
    if (schemaGeneration(metric) < (newestGeneration.get(seriesKey(metric)) ?? 0)) {
      continue;
    }

    // Anything the newest push superseded, including a verdict family carrying
    // no run id at all once one carrying one exists — those predate the labels
    // and are older by construction. See newestPush above.
    const suffix = metricSuffix(metric.__name__ ?? '');
    if (VERDICT_SUFFIXES.has(suffix)) {
      const key = seriesKey(metric);
      const newest = newestPush.get(key);
      const familyIsIdentified = identified.get(key)?.has(suffix) ?? false;
      // An unidentified sample is only superseded once its own family has
      // migrated; until then it is the only word there is. See `identified`.
      const orderable = metric.run_id !== undefined || familyIsIdentified;
      if (
        newest !== undefined &&
        orderable &&
        isNewerPush(newest, { runId: metric.run_id, runAttempt: metric.run_attempt })
      ) {
        continue;
      }
    }

    const entry = entryFor(metric);
    // Prometheus always returns the sample value as a STRING — never assume numeric.
    const num = Number(value[1]);
    if (Number.isNaN(num)) {
      continue;
    }

    switch (suffix) {
      case 'status':
        entry.passed = num === 1;
        entry.hasStatus = true;
        break;
      case 'timestamp_seconds': {
        // A window can hand back more than one timestamp series for a service:
        // a gateway pod duplicate the aggregation did not collapse, or a `repo`
        // label that changed. The newest push is the one that describes the
        // current verdict, so an older duplicate must never overwrite it and
        // report a live service as older than it is.
        const finishedAtMs = num * 1000;
        if (finishedAtMs < entry.finishedAt.getTime()) break;
        entry.finishedAt = new Date(finishedAtMs);
        break;
      }
      case 'total':
        if (metric.result && metric.result in entry.counts) {
          entry.counts[metric.result as keyof ServiceBlockingStatus['counts']] = num;
        }
        break;
      case 'run_info':
        // run_id is a LABEL, so a new run is a new series rather than a new
        // value on an existing one, and a window returns every run it covers —
        // doc2-api had four inside 7d when this was written. The sample
        // timestamps are all the query time and cannot order them, so order on
        // the run id. Taking whichever series happened to arrive last would put
        // a days-old commit and build number next to a fresh verdict.
        if (
          entry.runId === undefined ||
          isNewerPush(
            { runId: metric.run_id, runAttempt: metric.run_attempt },
            { runId: entry.runId, runAttempt: entry.runAttempt }
          )
        ) {
          entry.runId = metric.run_id;
          entry.runAttempt = metric.run_attempt;
          entry.commit = metric.commit;
          entry.imageTag = metric.image_tag;
          entry.blockedBy = metric.blocked_by;
        }
        break;
      case 'outcome':
        // Pushed under the gate family's grouping key, so this lands on the row
        // it describes. Value carries the verdict (1 = rolled out), the label
        // carries WHY — a failed rollout and a deploy that never started are
        // both `deployOk === false` and are told apart only by `deployResult`.
        // EVERY RUN WITH A DIFFERENT OUTCOME IS A DIFFERENT SERIES.
        //
        // deploy_result and failed_stage are LABELS, so a run that failed and a
        // run that succeeded do not overwrite one another — they are two series,
        // and a windowed read returns both. They fold onto one row here, so
        // without a rule the row is last-writer-wins over a result Prometheus
        // does not order: a green row for a service whose last deploy failed, or
        // the reverse, chosen at random. doc2-api read DEPLOYED while its newest
        // run had been blocked, which is how this was found.
        //
        // So the same rule `_run_info` has always used: order on the run id and
        // let the newest win. A sample carrying one always beats a sample without
        // (those predate the label, so they are older by construction) — which
        // also covers the samples pushed before failed_stage existed.
        //
        // Run id ALONE is not that rule, though, and reading it as such is what
        // DEVO-175 was: a RE-RUN KEEPS ITS RUN ID, so attempt 1 of a restarted
        // pipeline and attempt 2 tie on it. Attempt 1 has usually already
        // published an outcome by then — a cancelled attempt still reaches the
        // reporter, and reports `skipped`/`upstream` — so the tie is between an
        // abandoned attempt's verdict and the real one, and a tie means the fold
        // keeps whichever Prometheus listed first. A green fulltext-service dev
        // deploy read FAILED across the whole board that way. isNewerPush breaks
        // the tie on `run_attempt`, exactly as `_run_info` above already does.
        if (entry.hasDeployOutcome) {
          const candidate = { runId: metric.run_id, runAttempt: metric.run_attempt };
          const held = { runId: entry.deployRunId, runAttempt: entry.deployRunAttempt };
          if (candidate.runId !== undefined || held.runId !== undefined) {
            // At least one is ordered: only a genuinely later push wins, and a
            // sample with no run id loses to one that has it.
            if (!isNewerPush(candidate, held)) break;
          } else {
            // NEITHER is ordered, so fall back to the schema generation the way
            // schemaGeneration() does for `track`: failed_stage was added after
            // the family shipped, so a sample carrying it is the newer push. Only
            // when that cannot separate them either is the held one kept — an
            // arbitrary but STABLE choice, so one render cannot disagree with the
            // next.
            if (!(metric.failed_stage && !entry.failedStage)) break;
          }
        }
        entry.hasDeployOutcome = true;
        entry.deployOk = num === 1;
        entry.deployResult = metric.deploy_result;
        entry.failedStage = metric.failed_stage;
        entry.deployRunId = metric.run_id;
        entry.deployRunAttempt = metric.run_attempt;
        break;
      case 'suites_total':
        entry.suites = num;
        break;
      case 'configured':
        entry.configured = num === 1;
        break;
      default:
        break;
    }
  }

  for (const entry of byKey.values()) {
    entry.totalTests = entry.counts.passed + entry.counts.failed + entry.counts.skipped;
  }

  // One service can legitimately hold two rows now — one per track — so `track`
  // breaks the tie and keeps the order deterministic.
  return [...byKey.values()].sort(
    (a, b) => a.service.localeCompare(b.service) || a.track.localeCompare(b.track)
  );
}

/** The rows of one release line. */
export function statusesForTrack(
  statuses: ServiceBlockingStatus[],
  track: string
): ServiceBlockingStatus[] {
  return statuses.filter((entry) => entry.track === track);
}

/**
 * How many services actually report on each track.
 *
 * Drives the track switch, and is the honest answer to "is NOVA reporting yet?"
 * — a zero is not a failure, it is a line whose pipelines do not publish a gate
 * verdict yet. Counts only rows Prometheus returned; placeholders are excluded
 * because a placeholder is the absence of a report, not one.
 */
export function trackReportCounts(
  statuses: ServiceBlockingStatus[]
): Record<ReleaseTrack, number> {
  const counts = { vesta: 0, nova: 0 } as Record<ReleaseTrack, number>;
  for (const entry of statuses) {
    if (entry.hasMetrics && entry.track in counts) {
      counts[entry.track as ReleaseTrack] += 1;
    }
  }
  return counts;
}

/**
 * Classify a gate for display.
 *
 * Order matters: an unconfigured gate is not a pass, and a gate that ran no
 * blocking tests is not a pass either (the CI template treats pytest exit code 5
 * — "no tests collected" — as success).
 *
 * FOUR SITUATIONS, NOT ONE
 * ------------------------
 * 'not-configured' used to absorb every row without a usable verdict, and read
 * on the board as "this service has no blocking tests". Four unrelated
 * situations were involved, and they are now four states:
 *
 *   configured=0                      → 'not-configured'. Nothing gates this
 *                                       service. A settled, if empty, answer.
 *   no verdict, nothing measured      → 'did-not-run'. The gate is wired up and
 *                                       never reached a verdict. Unverified.
 *   no verdict, something measured    → 'incomplete'. Suites genuinely ran and
 *                                       the run was cut short before a verdict.
 *                                       The partial counts are REAL DATA and
 *                                       are rendered as measured, not discarded.
 *   a verdict describing this run     → 'failing' / 'no-tests' / 'passing'.
 *
 * Splitting 'did-not-run' from 'incomplete' rather than merging them is
 * deliberate. Both are unverified and both must be styled as such, but they are
 * different facts about the fleet: barcode-service measured nothing at all,
 * while doc2app ran a suite and produced 13-14 real passed tests before being
 * interrupted. Presenting doc2app as unmeasured would be a second false
 * statement, of the same kind this change exists to remove.
 *
 * AGE IS NOT A STATE, DELIBERATELY
 * --------------------------------
 * This used to return 'stale' for a verdict older than 24h, ahead of the pass
 * check, so a green gate from two days ago rendered as a warning. That is wrong
 * for this fleet: several services legitimately deploy about once a week, so the
 * board reported normal operation as a fault and taught its readers to discount
 * it. A green verdict from six days ago is a green verdict. The age is reported
 * beside it, neutrally, and the "Reported" column sorts by it.
 *
 * No larger threshold replaces the old one, because ANY fixed threshold is wrong
 * for a fleet with mixed release cadences — a bigger number would only move which
 * services it libels. Age has to be judged against a service's own cadence, and
 * this board does not know that.
 *
 * The original reason for the harsh treatment is covered elsewhere now. 'stale'
 * was introduced because `operator` showed a green verdict beside 4 failures from
 * the retired Allure-era schema; schemaGeneration() disqualifies pre-schema rows
 * outright, so a superseded verdict no longer reaches this function at all.
 */
/**
 * True when the newest run says the gate did not run, so any verdict in the
 * window belongs to an EARLIER run and cannot describe the current one.
 *
 * This is the whole reason the state derivation cannot read `hasStatus` alone.
 * The board queries `last_over_time(...[7d:5m])`, so a series does not have to
 * be current to be returned — it only has to have existed once inside the
 * window. barcode-service on `dev` (measured 2026-08-27) is the case in point:
 *
 *   _status                      = 1        ← 11:08 UTC, the last run that ran
 *   tests_total{passed|failed}   = 0        ← 11:12 UTC, the run that did not
 *   suites_total                 = 0        ← 11:12 UTC
 *   run_info{blocked_by="did-not-run"}      ← 11:12 UTC, newest run id
 *
 * One row, two runs. The pushgateway has no TTL and its PUT is per group, so
 * the later run replaced the counts and run_info but published no verdict of
 * its own — and the older green sample stays reachable through the window until
 * it ages out. Reading `hasStatus` alone therefore presents a superseded green
 * as the current one for a week.
 *
 * `run_info` is the tie-break because it is the only family that identifies its
 * own run: `run_id` is a LABEL, so the newest run is resolvable by id (see
 * isNewerRun) and `blockedBy` always holds the newest run's marker. The sample
 * timestamps cannot be used for this — `last_over_time` reports every sample at
 * query time, so all families look equally fresh no matter which run pushed
 * them.
 *
 * The inverse never needs guarding: a run that did not run publishes no
 * _status, so a verdict and a `did-not-run` marker can never come from the same
 * run.
 */
function verdictSuperseded(status: ServiceBlockingStatus): boolean {
  return status.blockedBy === 'did-not-run';
}

/**
 * Whether anything actually executed, however little.
 *
 * `suites_total` is the honest signal and is preferred; the test counts are the
 * fallback for services that never published the suite family. A real zero must
 * stay representable, so this asks what the numbers say rather than assuming a
 * zero is fabricated — today every group in the fleet that holds a verdict also
 * holds non-zero counts, but that is an observation about the fleet, not a rule
 * to hardcode.
 */
function measuredSomething(status: ServiceBlockingStatus): boolean {
  return (status.suites ?? 0) > 0 || status.totalTests > 0;
}

export function gateState(status: ServiceBlockingStatus): BlockingGateState {
  if (!status.hasMetrics) return 'no-metrics';
  if (!status.configured) return 'not-configured';
  // No verdict describes the current run — either none is in the window at all,
  // or the newest run says it never reached one. Deliberately ahead of the
  // pass/fail checks: this is what stops a superseded green from being rendered
  // as the current verdict.
  if (verdictSuperseded(status) || !status.hasStatus) {
    return measuredSomething(status) ? 'incomplete' : 'did-not-run';
  }

  // A TEST FAILURE IS THE ONLY THING THAT MAKES THE TEST GATE RED.
  //
  // `status = 0` does NOT mean a test failed. It means "this service was not
  // allowed to deploy", and the gate aggregates non-test jobs too — a migration,
  // the chain validation, the version tagging. Reading it as a test verdict is
  // the conflation this whole split exists to remove, and it produced exactly
  // the row that motivated the split: auth-service with 130 passed, 0 failed and
  // `blocked_by="tag-git-version"`, rendered as FAILING in a column about tests.
  //
  // So the test column now reports what the TESTS did, and nothing else. A block
  // with no test failure behind it belongs to the Deployment status column,
  // which says nothing shipped and names the stage that stopped it — see
  // deploymentState(). The desk page adds an inline caveat so a green test
  // column on a blocked deploy cannot be misread as "all fine".
  if (!status.passed) {
    // Blocked. Was it a test that blocked it? Only then is the TEST gate red.
    if (status.counts.failed > 0 || blockedByClasses(status.blockedBy).has('test')) {
      return 'failing';
    }
    // No test failure behind the block: report what the tests actually did.
    return status.totalTests === 0 ? 'no-tests' : 'passing';
  }

  // A PASS verdict is left as the gate reported it, including the contradictory
  // "success despite N failed" case: that one keeps its green state and an
  // explicit caveat beside it, which is long-standing behaviour and a different
  // finding from the one above. Only a BLOCK is reinterpreted here.
  if (status.totalTests === 0) return 'no-tests';
  return 'passing';
}

/**
 * Gate states from "read this first" to "carries no information" — the order the
 * Test status column sorts by, and the board's tie-break (see sortForBoard,
 * which now leads on failed-first then report time).
 *
 * A red gate outranks everything. Then the two states with no verdict for the
 * current run — the gate that measured nothing at all ahead of the one that at
 * least measured something before being cut short, since less is known about
 * the first. Then the two states that reported something but settled nothing: a green verdict
 * with no tests behind it, and a service declaring that nothing gates its
 * deployment. Then the genuine passes. Rows with
 * no series at all come last — they are placeholders this app invents from its own
 * registry rather than anything a service said, they outnumber the reporting
 * services today, and a board that opens on ten grey rows buries the ones that
 * mean something.
 */
export const GATE_ORDER: readonly BlockingGateState[] = [
  'failing',
  'did-not-run',
  'incomplete',
  'no-tests',
  'not-configured',
  'passing',
  'no-metrics',
];

export function gateRank(state: BlockingGateState): number {
  return GATE_ORDER.indexOf(state);
}

// ============================================================================
// Deployment status — the second, independent verdict (DOCB-14207 / DEVO-150)
// ============================================================================

/**
 * What a `blocked_by` value is: a gate JOB name, and which kind of job.
 *
 * `blocked_by` is caller-defined free text — the comma-separated, sorted keys of
 * the `gate-results` object whose value was `failure`, chosen by whoever wrote
 * that caller workflow. There are two producer generations and no closed
 * vocabulary, so this list is MAINTAINED BY HAND and is the only thing that lets
 * the page say whether a block came from a test or from a non-test deploy step.
 *
 * 'test'        — a test job said no. Belongs to the Test status column.
 * 'deploy-step' — a NON-test step of the deployment said no: a migration, the
 *                 chain validation, the git tagging. The tests may well be
 *                 green; this is the auth-service case that motivated splitting
 *                 the columns (130 passed, blocked_by="tag-git-version").
 * 'not-run'     — no gate reached a verdict at all (see verdictSuperseded).
 * 'unnamed'     — the producer's own documented reporting bug: the gate did not
 *                 pass, yet every key reported success. The block is REAL and
 *                 the reason is missing. Never rendered as OK, and never blamed
 *                 on a test.
 *
 * Anything absent from this map is 'unknown-value' (see blockedByClasses) and
 * renders as unverified — never as a pass. Adding an entry is a deliberate act:
 * verify the string against a live push before you classify it, exactly as with
 * SERVICE_LABEL_MAP.
 *
 * Sources, both verified rather than guessed:
 *   - the templated deployment's `gate-results` in DevOps/.github/workflows/deploy.yml
 *     (smoke, critical, suite, validate-chain-*, apply-migration-*)
 *   - every value live in Prometheus over 30d on 2026-08-27 (the older
 *     repo-level callers: tests, pytest-suite, smoke-test, tag-git-version,
 *     version, validation)
 *   - DevOps/.github/docs/DEPLOY_GATE_METRICS.md for did-not-run and unknown
 */
export type BlockedByClass = 'test' | 'deploy-step' | 'not-run' | 'unnamed' | 'unknown-value';

export const BLOCKED_BY_CLASS: Record<string, Exclude<BlockedByClass, 'unknown-value'>> = {
  // Templated deployment (deploy.yml gate-results keys)
  smoke: 'test',
  critical: 'test',
  suite: 'test',
  'validate-chain-eu': 'deploy-step',
  'validate-chain-us': 'deploy-step',
  'apply-migration-eu': 'deploy-step',
  'apply-migration-us': 'deploy-step',
  // doc2app's deploy gate, one key per lane (DOCB-14280). It used to be the
  // single `tests` job; splitting it into parallel lanes is what lets
  // blocked_by name the lane that actually stopped the deploy instead of
  // collapsing every failure into "tests". All six are 'test' because all six
  // are the test gate — they run before anything deploys, and none of them is
  // a deployment step in the sense this map means (a migration, the chain
  // validation, the git tagging). That is exactly what `tests` meant when it
  // was one job, so the two columns keep reading the same thing they did.
  'static-checks': 'test',
  'unit-tests': 'test',
  'component-tests': 'test',
  'integration-tests': 'test',
  'build-gate': 'test',
  aggregate: 'test',
  // Older repo-level callers, all observed live
  tests: 'test',
  'pytest-suite': 'test',
  'smoke-test': 'test',
  'critical-tests': 'test',
  'tag-git-version': 'deploy-step',
  version: 'deploy-step',
  validation: 'deploy-step',
  // Collector-defined, not job names
  'did-not-run': 'not-run',
  unknown: 'unnamed',
};

/**
 * Every class named by a `blocked_by` value, which can name SEVERAL jobs.
 *
 * The label is comma-separated when more than one gate job failed, so a run can
 * be blocked by a test AND a migration at once. Returning the set rather than
 * one winner is what lets the two columns each read their own half of it without
 * either overruling the other.
 *
 * An empty or absent label yields an empty set — "nothing blocked this", which
 * is a fact about blocking and NOT a statement that the rollout succeeded.
 */
export function blockedByClasses(blockedBy?: string): Set<BlockedByClass> {
  const classes = new Set<BlockedByClass>();
  for (const raw of (blockedBy ?? '').split(',')) {
    const value = raw.trim();
    if (!value) continue;
    classes.add(BLOCKED_BY_CLASS[value] ?? 'unknown-value');
  }
  return classes;
}

/**
 * Did the service actually roll out?
 *
 * Independent of gateState() on purpose: the gate answers "was this allowed to
 * deploy", decided before Helm runs, and the two answers genuinely differ — a
 * green gate whose Helm upgrade then failed is Test=passing, Deployment=failed.
 *
 *   'failed'      — the rollout ran and did not succeed, or a non-test deploy
 *                   step (migration, chain validation, tagging) stopped it.
 *   'blocked'     — the test gate stopped it, so no deploy was attempted. The
 *                   reason lives in the Test status column; this column only
 *                   reports that nothing shipped.
 *   'not-deployed'— no deploy happened and no gate failed it: skipped, or a
 *                   pipeline that died before reaching the deploy.
 *   'unverified'  — something rejected this build but nothing here names what,
 *                   or the value naming it is not in BLOCKED_BY_CLASS. The
 *                   explicit "we do not know" bucket; never styled as a pass.
 *   'unknown'     — the honest state for the whole fleet until DEVO-150 ships:
 *                   the gate allowed the deploy and no rollout metric exists, so
 *                   whether Helm succeeded is genuinely not known here.
 *   'deployed'    — the rollout succeeded. Only docbits_deploy_outcome can say
 *                   this; no combination of gate metrics ever implies it.
 *   'no-metrics'  — placeholder row, nothing reported at all.
 */
export type DeploymentState =
  | 'failed'
  | 'blocked'
  | 'not-deployed'
  | 'unverified'
  | 'unknown'
  | 'deployed'
  | 'no-metrics';

export function deploymentState(status: ServiceBlockingStatus): DeploymentState {
  if (!status.hasMetrics) return 'no-metrics';

  const classes = blockedByClasses(status.blockedBy);

  // The rollout metric outranks every inference below — it is the only direct
  // observation of what Helm did. Read before the fallbacks, not after.
  if (status.hasDeployOutcome) {
    if (status.deployOk) return 'deployed';

    // The stage is the producer's own answer to "what broke", so it outranks
    // every inference from blocked_by — but only for the WORDING. It never
    // softens the verdict: `deployOk` is already false here, which means nothing
    // shipped, and that is the finding whether or not CI could name a stage.
    // Only 'rollout' says the Helm upgrade itself failed; every other stage
    // means the deploy never ran, which is not the same finding.
    switch (status.failedStage) {
      case 'rollout':
        return 'failed';
      case 'tests':
        return 'blocked';
      case 'upstream':
      case 'version':
      case 'chain-validation':
      case 'migration':
        // Something before the deploy broke. Still a failed DEPLOYMENT — nothing
        // shipped and somebody has to act — but the reason names the real stage
        // so nobody is sent to the Helm logs.
        return 'failed';
      default:
        // 'unknown', or no stage label at all (a series pushed before DEVO-150).
        // Deliberately NOT 'unverified': being unable to name the stage is a gap
        // in the REASON, not doubt about the outcome. The run told us it did not
        // deploy, so the row stays a stop — softening it to amber is how a
        // service that shipped nothing came to sit beside the healthy ones.
        break;
    }

    // Fall back to what the result alone can carry.
    if (status.deployResult === 'skipped') {
      // A skipped deploy is "nothing shipped". WHY it was skipped still comes
      // from the gate: a failed test gate is a block, anything else is not.
      return classes.has('test') ? 'blocked' : 'not-deployed';
    }
    return 'failed';
  }

  // ── Fallback while DEVO-150 is not yet emitting (and for older data) ──
  // A non-test deploy step that reported failure is a failed deployment on its
  // own evidence — no rollout metric needed.
  if (classes.has('deploy-step')) return 'failed';
  if (classes.has('test')) return 'blocked';
  // Blocked by something this app cannot name. Explicitly not OK.
  if (classes.has('unnamed') || classes.has('unknown-value')) return 'unverified';
  if (classes.has('not-run')) return 'not-deployed';
  if (!status.configured) return 'unknown';
  // Nothing blocked it and nothing observed the rollout.
  return status.hasStatus && !status.passed ? 'blocked' : 'unknown';
}

/**
 * Deployment states from "read this first" to "carries no information", mirroring
 * GATE_ORDER so this column's sort and the gate column's cannot drift.
 */
export const DEPLOYMENT_ORDER: readonly DeploymentState[] = [
  'failed',
  // Both of these mean nothing shipped, so they sort ABOVE 'unverified', which
  // only means we could not read the outcome. Matches TONE_SEVERITY — a column
  // that sorted a stopped deploy below an unread one would contradict its own
  // colours.
  'blocked',
  'not-deployed',
  'unverified',
  'unknown',
  'deployed',
  'no-metrics',
];

export function deploymentRank(state: DeploymentState): number {
  return DEPLOYMENT_ORDER.indexOf(state);
}

/**
 * Whether a row is "failed" for the purposes of floating to the top of the board.
 *
 * EITHER column counts (Gregor's decision, DOCB-14207): a red test gate and a
 * failed rollout are both things somebody has to act on, and a board that
 * floated only one of them would bury the other behind a screen of passing rows.
 *
 * "Failed deployment" here is every state that means NOTHING SHIPPED, not the
 * single state named 'failed'. Listing only that one is why a red NOT DEPLOYED
 * row sorted by recency and landed below a green one — the row was painted red
 * by rowTone and then ordered as if it were fine.
 *
 * This list must stay exactly the set of deployment states whose tone is
 * 'blocked'. It cannot read the tone directly — the presentation map lives in
 * blockingGateBoard, which imports THIS file, and reaching back would close an
 * import cycle — so a test in blockingGateBoard.unit.spec.ts asserts the two
 * agree in both directions.
 */
export const STOPPED_DEPLOYMENT_STATES: readonly DeploymentState[] = [
  'failed',
  'blocked',
  'not-deployed',
];

export function isFailedRow(status: ServiceBlockingStatus): boolean {
  return (
    gateState(status) === 'failing' ||
    STOPPED_DEPLOYMENT_STATES.includes(deploymentState(status))
  );
}

/**
 * The board's default order: anything failed first, then most recently reported.
 *
 * "Failed" is EITHER column — a red test gate or a failed rollout (isFailedRow).
 * Both need somebody to act, and floating only one of them would bury the other.
 *
 * Second key is the report time, NEWEST FIRST, which is what makes the rest of
 * the board useful: below the failures a reader wants the deployments that just
 * happened, not an arbitrary slice of the fleet. Placeholder rows sort to the
 * bottom for free — they carry the epoch as their finishedAt because nothing ever
 * reported them.
 *
 * The gate ranking is only a tie-break now, so GATE_ORDER still decides what
 * comes first among rows reported at the same instant, and remains what the Test
 * status column sorts by.
 *
 * THE OLD ORDER RAN ON THE TEST-CASE COUNT AND DELIBERATELY NO LONGER DOES.
 * The count is how many cases can stop a service's deployment and nothing else —
 * ocr-service reporting 1 is not worse than doc2-api reporting 14,296 — so
 * ordering the board by it read as a quality ranking it was never able to be.
 * It is still the "Blocking cases" column, still sortable, just not the default.
 *
 * This is the DEFAULT order only. The table renders rows as given while no column
 * is sorted (`pagination.sortBy: null`), and any user-sortable column takes over
 * the moment its header is clicked.
 */
export function sortForBoard(statuses: ServiceBlockingStatus[]): ServiceBlockingStatus[] {
  return [...statuses].sort(
    (a, b) =>
      Number(isFailedRow(b)) - Number(isFailedRow(a)) ||
      b.finishedAt.getTime() - a.finishedAt.getTime() ||
      gateRank(gateState(a)) - gateRank(gateState(b)) ||
      serviceDisplayName(a.service).localeCompare(serviceDisplayName(b.service))
  );
}

/** Deep link to the GitHub Actions run that produced the metric. */
export function runUrl(status: ServiceBlockingStatus): string | null {
  if (!status.runId || !status.repo) return null;
  return `https://github.com/FELLOWPRO/${status.repo}/actions/runs/${status.runId}`;
}

/**
 * CI service labels do not match the service keys used in the web app
 * (DOCB-13956). Map what we know; fall back to a prettified label so a newly
 * onboarded service still renders sensibly instead of disappearing.
 *
 * A missing entry does not just cost a nice name — it splits a service into two
 * rows. Without a `webKey` the metric row cannot be matched to the placeholder
 * built from the app's own registry, so the service appears twice: once under a
 * prettified CI label with real numbers, and once as "no gate metric". That is
 * what "Doc2 Api" beside an empty "API Service" was.
 *
 * The keys here are the `service` label as CI emits it. Those come from the
 * `name` field of DevOps/services/registry.yaml, so the authoritative list is
 * that file, NOT this app's service keys — several differ (`doc2-api` vs `api`,
 * `ftp-import` vs `import-ftp`). Verify a new label against a live push
 * before adding it:
 *   {__name__="docbits_deploy_blocking_configured"}  on prometheus.docbits.com
 */
const SERVICE_LABEL_MAP: Record<string, { displayName: string; webKey?: string }> = {
  docflow: { displayName: 'DocFlow', webKey: 'docflow' },
  barcode: { displayName: 'Barcode Service', webKey: 'barcode' },
  docnet: { displayName: 'DocNet', webKey: 'docnet' },
  pomatch: { displayName: 'PO Matching', webKey: 'po-match' },
  'pomatch-service': { displayName: 'PO Matching', webKey: 'po-match' },
  ocr: { displayName: 'OCR Service', webKey: 'ocr' },
  importemail: { displayName: 'Email Import', webKey: 'email-import' },
  'importemail-service': { displayName: 'Email Import', webKey: 'email-import' },
  'import-ftp': { displayName: 'Import FTP', webKey: 'import-ftp' },
  'import-ftp-service': { displayName: 'Import FTP', webKey: 'import-ftp' },
  operator: { displayName: 'DOCOperator', webKey: 'docoperator' },
  docoperator: { displayName: 'DOCOperator', webKey: 'docoperator' },
  autoaccounting: { displayName: 'Auto Accounting', webKey: 'auto-accounting' },
  fulltext: { displayName: 'Fulltext Search', webKey: 'fulltext' },
  'fulltext-service': { displayName: 'Fulltext Search', webKey: 'fulltext' },
  extraction: { displayName: 'Extraction Service', webKey: 'extraction' },
  auth: { displayName: 'Auth Service', webKey: 'auth' },
  api: { displayName: 'API Service', webKey: 'api' },
  web: { displayName: 'Web Application', webKey: 'web' },
  watchdog: { displayName: 'WatchDog Service', webKey: 'watchdog' },
  'ideas-service': { displayName: 'Ideas Service' },

  // The registry names CI actually pushes, where they differ from the short key
  // above. Each was confirmed against a live series on prometheus.docbits.com.
  'doc2-api': { displayName: 'API Service', webKey: 'api' },
  'ocr-service': { displayName: 'OCR Service', webKey: 'ocr' },
  'barcode-service': { displayName: 'Barcode Service', webKey: 'barcode' },
  'auth-service': { displayName: 'Auth Service', webKey: 'auth' },
  'extraction-service': { displayName: 'Extraction Service', webKey: 'extraction' },
  'ftp-import': { displayName: 'Import FTP', webKey: 'import-ftp' },
  // This app itself. CI labels it `doc2app` — the name SERVICE_NAME, the
  // DO_APP_ID_* variables and envs/doc2app.env all use — while the app's own
  // service registry calls it `web`. Without this alias the real verdict would
  // render as a second row named "Doc2app" beside the `web` placeholder, which
  // is the duplicate this map exists to prevent.
  doc2app: { displayName: 'Web Application', webKey: 'web' },

  // Web-app service keys as aliases, so placeholder rows built from the app's
  // own service registry resolve to the same display names as CI labels.
  'po-match': { displayName: 'PO Matching', webKey: 'po-match' },
  'email-import': { displayName: 'Email Import', webKey: 'email-import' },
  'auto-accounting': { displayName: 'Auto Accounting', webKey: 'auto-accounting' },
};

export function serviceDisplayName(label: string): string {
  const mapped = SERVICE_LABEL_MAP[label.toLowerCase()];
  if (mapped) return mapped.displayName;
  return label
    .replace(/[-_]/g, ' ')
    .replace(/\b\w/g, (character) => character.toUpperCase());
}

/** Web-app service key for deep linking into /tests/:serviceName, when one exists. */
export function serviceWebKey(label: string): string | null {
  return SERVICE_LABEL_MAP[label.toLowerCase()]?.webKey ?? null;
}

/**
 * Add a placeholder row for every known service that Prometheus reports nothing
 * for, so the table lists the whole estate rather than only the services whose
 * CI gate happens to be wired up.
 *
 * Coverage is still partial (DOCB-13956), so a placeholder is not a defect.
 * Reporting as of 2026-08-13: doc2-api, docnet, ocr-service, email-import and
 * auto-accounting push real numbers; operator and DocFlow have the reporter
 * merged but last pushed before the counts existed; auth-service,
 * fulltext-service, ftp-import and extraction-service are not wired up yet;
 * ideas-service reports `configured=0` because nothing gates its deployment,
 * which is a verdict of its own and not the same thing as a placeholder.
 * DocBits_Web reports under the CI label `doc2app`: its `version & deploy` job
 * is gated by the `tests` job, whose ten continue-on-error: false checks are the
 * gate. Its Playwright suite is not part of it (DOCB-13416) and so contributes
 * no metrics.
 * All of those must read as "no gate metric", never as absent.
 *
 * ONE TRACK AT A TIME — the caller's obligation
 * ---------------------------------------------
 * Coverage is keyed on `service` alone, because a placeholder answers "does the
 * app know about a service Prometheus is silent about?" and that question has no
 * environment or track in it. Which means `statuses` must already be narrowed to
 * a single release line, or the answer is wrong in the one direction that
 * matters: a service reporting on VESTA and not on NOVA would count as covered,
 * no placeholder would be added, and the missing NOVA verdict — the finding —
 * would silently disappear instead of showing up as "no gate metric".
 *
 * @param statuses - grouped Prometheus results, ALREADY narrowed to one track
 * @param knownServices - service keys from the app's own registry
 * @param environment - selected environment, or '' when showing all
 * @param track - the release line these rows belong to; placeholders inherit it
 */
export function mergeWithKnownServices(
  statuses: ServiceBlockingStatus[],
  knownServices: string[],
  environment: string,
  track: ReleaseTrack = DEFAULT_TRACK
): ServiceBlockingStatus[] {
  const covered = new Set(
    statuses.map((entry) => serviceWebKey(entry.service) ?? entry.service.toLowerCase())
  );

  const placeholders: ServiceBlockingStatus[] = knownServices
    .filter((key) => !covered.has(key.toLowerCase()))
    .map((key) => ({
      service: key,
      environment: environment || 'any',
      track,
      passed: false,
      finishedAt: new Date(0),
      counts: { passed: 0, failed: 0, skipped: 0 },
      configured: false,
      hasStatus: false,
      totalTests: 0,
      hasMetrics: false,
      hasDeployOutcome: false,
    }));

  // Returned in the board's default order rather than alphabetically: the table
  // renders rows as given until a column header is clicked, so this is what a
  // reader sees first. See sortForBoard().
  return sortForBoard([...statuses, ...placeholders]);
}

// ============================================================================
// Service
// ============================================================================

export class DeployBlockingTestsPrometheusService {
  private readonly logPrefix = '[DeployBlockingTestsPrometheus]';

  /**
   * One request returns every metric for every service on BOTH release lines,
   * over a window rather than at an instant, so a service that has not reported
   * since the gateway last lost its groups is still returned — with its age, not
   * as missing.
   *
   * Reading both tracks in one request is deliberate: it is what lets a consumer
   * say which lines report at all, and switching between them costs no round
   * trip. Pass `track` only to read one line in isolation.
   *
   * @param environment - when given, filtered server-side via the label matcher
   * @param track - when given, restricts the read to one release line
   */
  async getBlockingStatuses(
    environment?: string,
    track?: ReleaseTrack
  ): Promise<ServiceBlockingStatus[]> {
    const query = buildBlockingStatusQuery(environment, track);

    logger.info(`${this.logPrefix} Querying Prometheus`, {
      environment: environment ?? 'all',
      track: track ?? 'all',
      window: METRIC_WINDOW,
    });

    const response = await prometheusAxios.get<PromVectorResponse>('/api/v1/query', {
      params: { query },
    });

    const body = response.data;
    if (body?.status !== 'success') {
      throw new Error('Prometheus query failed');
    }

    const statuses = groupBlockingStatuses(body.data.result);

    logger.info(`${this.logPrefix} Grouped ${body.data.result.length} series`, {
      rows: statuses.length,
      reportingPerTrack: trackReportCounts(statuses),
      failing: statuses.filter((entry) => gateState(entry) === 'failing').length,
    });

    return statuses;
  }
}

export const deployBlockingTestsPrometheusService = new DeployBlockingTestsPrometheusService();
