/**
 * Presentation facts shared by the two renders of the blocking deployment test
 * status: the interactive desk page and the TV monitor view.
 *
 * Only what BOTH views must agree on lives here — what each gate state is
 * called, how alarming it is, and how a track's rows are derived. Everything
 * that differs between a desk and a wall stays in its own page: the desk page
 * owns its filters, KPI tiles and per-row links, and the monitor owns its
 * rotation and its type scale.
 *
 * The reason to share these two things in particular is that they are the parts
 * a reader would be misled by if the views disagreed. If one view called
 * 'did-not-run' "Never ran" and the other rendered it green, the fleet would
 * have two different answers to the same question — which is the class of bug
 * the truthful-gate-states work exists to remove. Row derivation is here for the
 * same reason: the one-track-at-a-time obligation that mergeWithKnownServices
 * documents is easy to get wrong, and getting it wrong silently hides a missing
 * NOVA verdict.
 */

// Imported from the defining modules rather than from './index': that barrel
// re-exports this file, so routing these through it would close an import cycle.
import {
  DEFAULT_TRACK,
  deploymentState,
  gateState,
  mergeWithKnownServices,
  statusesForTrack,
  trackBranchLine,
  type BlockingGateState,
  type DeploymentState,
  type ReleaseTrack,
  type ServiceBlockingStatus,
} from './deployBlockingTestsPrometheus.service';
import { SERVICE_DEFINITIONS } from './testsOverviewAggregator.service';

/**
 * How alarming a state is, independent of the words used for it.
 *
 * The point of a tone is that the wall display can colour by it without
 * re-deciding what each state means. Four values rather than the obvious
 * pass/fail two, because three of the seven states are neither:
 *
 *   'blocked'    — a gate said no. The only state that stops a deploy.
 *   'unverified' — no verdict describes the current run. NOT a pass, and must
 *                  never be styled like one; see the note below.
 *   'inert'      — a settled answer that carries no verdict either way: nothing
 *                  gates this service, or it publishes nothing at all.
 *   'good'       — a real verdict, from a run that measured something.
 *
 * 'no-tests' is deliberately 'unverified' rather than 'good'. The gate reported
 * success having run nothing, so the green is an artefact of pytest's "no tests
 * collected" exit code, not evidence about the service.
 */
export type GateTone = 'blocked' | 'unverified' | 'inert' | 'good';

export interface GateStatePresentation {
  /** Desk-page label. Unchanged wording — the desk page reads these verbatim. */
  label: string;
  /**
   * Monitor label. Shorter and upper-case, because it is read across a room at
   * a glance rather than scanned in a dense table.
   *
   * Shortened but never softened: 'NEVER RAN' and 'CANCELLED' still say plainly
   * that nothing was established. A wall display has no tooltip to qualify a
   * reassuring word with, so the word itself has to carry the whole meaning.
   */
  tvLabel: string;
  icon: string;
  /** Desk-page hover text. The monitor has no hover and never renders this. */
  explain: string;
  tone: GateTone;
}

/**
 * Everything that varies per gate state, in one place.
 *
 * Purely presentational: the ORDER these states carry lives in GATE_ORDER in
 * the service, so the board's default grouping and the desk table's Gate status
 * sort cannot drift apart from each other or from this map.
 */
