/**
 * How alarming a ROW is: the worse of its two columns.
 *
 * The row indicator — the dot and the coloured rail — used to read the test
 * verdict alone, which is how auth-service came to sit under a GREEN dot while
 * its deployment had failed at version tagging. A reader scanning the rail sees
 * one signal per row, so that signal has to account for both columns or it
 * quietly contradicts the cells beside it.
 *
 * Severity order, worst first:
 *
 *   'blocked'    — something said no. Loudest.
 *   'unverified' — no answer describes this run. Not a pass, so it outranks the
 *                  two settled tones.
 *   'inert'      — a settled answer carrying no verdict: nothing gates this, or
 *                  nothing shipped and nothing is wrong. Deliberately ABOVE
 *                  'good': green tests plus a deploy that never happened is not
 *                  a green row, because nothing reached production.
 *   'good'       — both columns are real and both are fine.
 */
const TONE_SEVERITY: readonly GateTone[] = ['blocked', 'unverified', 'inert', 'good'];

export function rowTone(status: ServiceBlockingStatus): GateTone {
  const testTone = GATE_STATE_PRESENTATION[gateState(status)].tone;
  const deployTone = DEPLOYMENT_STATE_PRESENTATION[deploymentState(status)].tone;
  return TONE_SEVERITY.indexOf(testTone) <= TONE_SEVERITY.indexOf(deployTone)
    ? testTone
    : deployTone;
}

/** The rows whose DEPLOYMENT failed, whatever their tests did. */
export function deployFailedRows(rows: ServiceBlockingStatus[]): ServiceBlockingStatus[] {
  return rows.filter((row) => deploymentState(row) === 'failed');
}

/**
 * The rows of one release line: that track's verdicts, plus a placeholder for
 * every service in the app's registry the track is silent about.
 *
 * Narrowing to one track BEFORE the merge is what makes the placeholders mean
 * anything, and is the reason this is a named function rather than two calls at
 * each site. mergeWithKnownServices keys coverage on the service name alone, so
 * handed both lines at once it would treat a VESTA-only reporter as covered and
 * quietly swallow the missing NOVA verdict — the exact finding the board exists
 * to surface.
 *
 * Comes back in the board's default order (sortForBoard).
 */
export function deriveTrackRows(
  reported: ServiceBlockingStatus[],
  track: ReleaseTrack,
  environment: string
): ServiceBlockingStatus[] {
  return mergeWithKnownServices(
    statusesForTrack(reported, track),
    SERVICE_DEFINITIONS.map((definition) => definition.service),
    environment,
    track
  );
}

/** The rows whose TEST gate actively stops a deployment. */
export function blockedRows(rows: ServiceBlockingStatus[]): ServiceBlockingStatus[] {
  return rows.filter((row) => gateState(row) === 'failing');
}

/**
 * The rows where nothing is getting deployed, whichever column is responsible.
 *
 * What a headline has to count. blockedRows() answers only about the test gate,
 * so a service whose tests are green and whose Helm rollout failed did not
 * appear in it — and the banner said "No service is failing" in green above a
 * red FAILED row. An all-clear that contradicts the table under it is worse than
 * no banner at all.
 *
 * Reads the row tone rather than either state list, so this and the per-row
 * indicator can never disagree about which rows are the alarming ones.
 */
export function stoppedRows(rows: ServiceBlockingStatus[]): ServiceBlockingStatus[] {
  return rows.filter((row) => rowTone(row) === 'blocked');
}

/** The rows for which no verdict describes the current run. */
export function unverifiedRows(rows: ServiceBlockingStatus[]): ServiceBlockingStatus[] {
  return rows.filter((row) => GATE_STATE_PRESENTATION[gateState(row)].tone === 'unverified');
}

/**
 * How a release line is named on the wall: `dev`, `dev Nova`.
 *
 * Deliberately NOT trackLabel(), which renders `NOVA (dev-nova)`. That form is
 * right for the desk page, where the parenthesised branch disambiguates a track
 * switch against the app's identically-named release channels. On the wall there
 * is no switch to disambiguate and no one to explain a branch name to: the
 * header simply says which line is on screen, in the words the team uses out
 * loud for it.
 */
export function lineDisplayName(track: ReleaseTrack, environment: string): string {
  const line = environment || 'dev';
  return track === DEFAULT_TRACK ? line : `${line} Nova`;
}

/**
 * The one headline the wall shows, worded as specified in DOCB-14201.
 *
 * "Blocked" here means a gate that actively said no, and nothing else. That is a
 * narrower claim than "everything is verified", which is why the monitor renders
 * monitorQualifier() underneath: an all-clear headline over a screen of
 * never-ran rows would be the reassuring-but-false reading this whole change
 * set exists to remove.
 */
export function monitorHeadline(rows: ServiceBlockingStatus[], line: string): string {
  const blocked = stoppedRows(rows).length;
  // Deliberately NOT "all services deploy successfully": most rows carry no
  // observed rollout at all, so that would claim something nothing measured. The
  // headline states the absence of a block, and monitorQualifier() states what
  // is still unverified underneath it.
  if (blocked === 0) return `No service is blocked on ${line}`;
  return `${blocked} ${blocked === 1 ? 'service is' : 'services are'} currently blocked on ${line}`;
}

/**
 * The sentence that stops the headline from overstating itself, or null when
 * there is nothing to qualify.
 *
 * Broken down per state rather than rolled into one "unverified" total, because
 * the three are different facts and the wall has no tooltip to separate them:
 * a service that never ran measured nothing, a cancelled one measured
 * something real before being interrupted, and one with no tests reached a
 * verdict that nothing stands behind. A single total would say "unverified" over
 * all three and lose which is which.
 *
 * Rendered as a plain second line under the headline rather than a badge, for
 * the same reason: there is nobody at the screen to ask what a badge means.
 */
export function monitorQualifier(rows: ServiceBlockingStatus[]): string | null {
  const tally = (state: BlockingGateState): number =>
    rows.filter((row) => gateState(row) === state).length;

  const parts: string[] = [];
  const neverRan = tally('did-not-run');
  const cancelled = tally('incomplete');
  const noTests = tally('no-tests');

  if (neverRan > 0) parts.push(`${neverRan} never ran`);
  if (cancelled > 0) parts.push(`${cancelled} cancelled`);
  if (noTests > 0) parts.push(`${noTests} ran no tests`);

  if (parts.length === 0) return null;
  return `${parts.join(' · ')} — unverified, not passing`;
}

/** Branch line a track means in an environment — re-exported for the monitor's header. */
export { trackBranchLine };
