import AbstractApiService from 'src/services/abstractApiService';
import { DOC2API_URL } from 'src/pages/APIs';

// ============================================================================
// TypeScript Response Interfaces (matches actual API response)
// ============================================================================

// Severity counts within a single trend point
export interface SeveritySnapshot {
  passed: number;
  failed: number;
  broken: number;
  skipped: number;
  unknown: number;
}

// A single point in the trend array
export interface TrendDataPoint {
  timestamp: string;
  by_severity: {
    critical?: SeveritySnapshot;
    normal?: SeveritySnapshot;
    minor?: SeveritySnapshot;
    trivial?: SeveritySnapshot;
    blocker?: SeveritySnapshot;
  };
  totals: {
    passed: number;
    failed: number;
    broken: number;
    skipped: number;
    unknown: number;
  };
  pass_rate?: number;
}

// Full response shape from GET /api/analytics/test-results/allure
export interface AllureTestResultsResponse {
  status: string;
  trend: TrendDataPoint[];
  meta: {
    days: number;
    step: string;
    start: string;
    end: string;
  };
}

// Chart-consumable format produced by the transformer
export interface ChartDataPoint {
  timestamp: string;
  passed: number;
  failed: number;
  skipped: number;
  total: number;
  pct_failed: number;
}

// ============================================================================
// Transformer
// ============================================================================

/**
 * Transform a trend array into chart-consumable data points for a given severity.
 * Computes total (sum of all statuses) and pct_failed (failed+broken out of total).
 */
export function transformTrendToChartData(
  trend: TrendDataPoint[],
  severity: keyof TrendDataPoint['by_severity']
): ChartDataPoint[] {
  return trend.map((point) => {
    const counts = point.by_severity[severity];
    const passed = counts?.passed ?? 0;
    const failed = counts?.failed ?? 0;
    const broken = counts?.broken ?? 0;
    const skipped = counts?.skipped ?? 0;
    const unknown = counts?.unknown ?? 0;
    const total = passed + failed + broken + skipped + unknown;
    const pct_failed = total > 0 ? ((failed + broken) / total) * 100 : 0;
    return {
      timestamp: point.timestamp,
      passed,
      failed: failed + broken,
      skipped,
      total,
      pct_failed,
    };
  });
}

// ============================================================================
// Service Class
// ============================================================================

export class TestStatisticsApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  /**
   * Fetch Allure test result statistics with trend data.
   * Calls GET /api/analytics/test-results/allure?days={days}&environment={environment}
   */
  public async getAllureTestResults(
    days: number = 7,
    environment?: string
  ): Promise<AllureTestResultsResponse> {
    const params = new URLSearchParams({ days: String(days) });
    if (environment) params.set('environment', environment);
    const endpoint = `${DOC2API_URL}/api/analytics/test-results/allure?${params}`;
    return await this.getWithoutOrgId<AllureTestResultsResponse>(endpoint);
  }
}

